/**
 * Shared Rust <-> TypeScript vector tests.
 *
 * `tests/vectors.json` is generated by `npm run vectors`, but the expected
 * canonical hex for the reference invoice is ALSO hardcoded here (copied
 * from `contract/src/tests/invoice_tests.rs`). The Rust unit suite reads the
 * same JSON and asserts its own Borsh bytes and Ed25519 signatures, so the
 * two implementations are checked against each other, not just themselves.
 *
 * Run with: npm run test:vectors
 */

import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

import {
  PROTOCOL_ID,
  PROTOCOL_VERSION,
  YOCTO_PER_NEAR,
  canonicalBytes,
  fromHex,
  nearToYocto,
  toHex,
  validateDomain,
  type SignedInvoice,
} from "../ts/src/borsh.ts";
import {
  fromBase64,
  hexToBytes,
  vendorKeyFromByte,
  verifySignature,
} from "../ts/src/keys.ts";

const vectorsPath = fileURLToPath(new URL("./vectors.json", import.meta.url));
const vectors = JSON.parse(readFileSync(vectorsPath, "utf8")) as {
  protocol_id: string;
  protocol_version: number;
  network_id: string;
  contract_id: string;
  signing_seed_hex: string;
  public_key: string;
  public_key_hex: string;
  reference_signature_hex: string;
  reference_signature_base64: string;
  cases: Array<{
    name: string;
    invoice: Record<string, string | number>;
    canonical_hex: string;
    signature_hex: string;
    signature_base64: string;
    domain_error: string | null;
  }>;
};

/** Copied verbatim from CANONICAL_VECTOR_HEX in invoice_tests.rs. */
const RUST_REFERENCE_HEX =
  "0c000000696e766f6963656775617264010000000700000073616e64626f781b000000" +
  "696e766f69636567756172642e756e69742e746573742e6e6561721500000076656e646f" +
  "722e756e69742e746573742e6e6561720700000000000000150000007061796f75742e75" +
  "6e69742e746573742e6e656172b2c9062ab62fc14c020000000000000080d8db7000000000";

function parseInvoice(raw: Record<string, string | number>): SignedInvoice {
  return {
    protocol_id: String(raw.protocol_id),
    protocol_version: Number(raw.protocol_version),
    network_id: String(raw.network_id),
    contract_id: String(raw.contract_id),
    vendor_id: String(raw.vendor_id),
    nonce: BigInt(raw.nonce),
    recipient: String(raw.recipient),
    amount: BigInt(raw.amount),
    expiration_unix_sec: BigInt(raw.expiration_unix_sec),
  };
}

const key = vendorKeyFromByte(1);

test("signing seed and public key are consistent across vectors", () => {
  assert.equal(vectors.protocol_id, PROTOCOL_ID);
  assert.equal(vectors.protocol_version, PROTOCOL_VERSION);
  assert.equal(key.nearPublicKey, vectors.public_key);
  assert.equal(Buffer.from(key.publicKey).toString("hex"), vectors.public_key_hex);
  assert.deepEqual(hexToBytes(vectors.signing_seed_hex), key.seed);
});

test("valid vector byte layout matches the independent Rust reference", () => {
  const valid = vectors.cases.find((c) => c.name === "valid");
  assert.ok(valid);
  assert.equal(valid.canonical_hex, RUST_REFERENCE_HEX);
  assert.equal(toHex(canonicalBytes(parseInvoice(valid.invoice))), RUST_REFERENCE_HEX);
});

test("every case serializes to its recorded canonical bytes", () => {
  for (const c of vectors.cases) {
    assert.equal(
      toHex(canonicalBytes(parseInvoice(c.invoice))),
      c.canonical_hex,
      `canonical bytes for ${c.name}`,
    );
  }
});

test("every case signature verifies against its own canonical bytes", () => {
  for (const c of vectors.cases) {
    const bytes = canonicalBytes(parseInvoice(c.invoice));
    assert.ok(
      verifySignature(bytes, fromBase64(c.signature_base64), key.publicKey),
      `base64 signature for ${c.name}`,
    );
    assert.ok(
      verifySignature(bytes, hexToBytes(c.signature_hex), key.publicKey),
      `hex signature for ${c.name}`,
    );
  }
});

test("reference signature only verifies for the exact signed invoice", () => {
  const reference = fromBase64(vectors.reference_signature_base64);
  assert.deepEqual(reference, hexToBytes(vectors.reference_signature_hex));
  const valid = vectors.cases.find((c) => c.name === "valid");
  assert.ok(valid);
  assert.ok(verifySignature(fromHex(valid.canonical_hex), reference, key.publicKey));

  for (const c of vectors.cases.filter((x) => x.name !== "valid")) {
    assert.notEqual(c.canonical_hex, valid.canonical_hex, `${c.name} changes the bytes`);
    assert.equal(
      verifySignature(fromHex(c.canonical_hex), reference, key.publicKey),
      false,
      `reference signature must not verify for ${c.name}`,
    );
  }
});

test("domain validation agrees with the Rust error codes", () => {
  for (const c of vectors.cases) {
    assert.equal(
      validateDomain(parseInvoice(c.invoice), vectors.network_id, vectors.contract_id),
      c.domain_error,
      `domain result for ${c.name}`,
    );
  }
});

test("every signed field is bound by the canonical bytes", () => {
  const base = parseInvoice(vectors.cases[0].invoice);
  const original = canonicalBytes(base);
  const mutations: Array<[string, (i: SignedInvoice) => void]> = [
    ["protocol_id", (i) => (i.protocol_id = "otherproto")],
    ["protocol_version", (i) => (i.protocol_version += 1)],
    ["network_id", (i) => (i.network_id = "testnet")],
    ["contract_id", (i) => (i.contract_id = "other.unit.test.near")],
    ["vendor_id", (i) => (i.vendor_id = "vendor2.unit.test.near")],
    ["nonce", (i) => (i.nonce += 1n)],
    ["recipient", (i) => (i.recipient = "payout2.unit.test.near")],
    ["amount", (i) => (i.amount += 1n)],
    ["expiration_unix_sec", (i) => (i.expiration_unix_sec += 1n)],
  ];
  for (const [name, mutate] of mutations) {
    const copy: SignedInvoice = { ...base };
    mutate(copy);
    assert.notEqual(toHex(canonicalBytes(copy)), toHex(original), `${name} is signed`);
  }
});

test("Borsh integer range checks reject invalid values", () => {
  const base = parseInvoice(vectors.cases[0].invoice);
  assert.throws(() => canonicalBytes({ ...base, nonce: -1n }), RangeError);
  assert.throws(() => canonicalBytes({ ...base, nonce: 1n << 64n }), RangeError);
  assert.throws(() => canonicalBytes({ ...base, amount: 1n << 128n }), RangeError);
  assert.throws(() => canonicalBytes({ ...base, amount: -1n }), RangeError);
  assert.throws(() => canonicalBytes({ ...base, protocol_version: -1 }), RangeError);
});

test("NEAR -> yoctoNEAR conversion uses exact integer arithmetic", () => {
  assert.equal(nearToYocto(1n), YOCTO_PER_NEAR);
  assert.equal(nearToYocto("1.5"), 1_500_000_000_000_000_000_000_000n);
  assert.equal(nearToYocto("0.000000000000000000000001"), 1n);
  assert.equal(nearToYocto("20"), 20n * YOCTO_PER_NEAR);
  assert.throws(() => nearToYocto("0.0000000000000000000000001"), RangeError);
  assert.throws(() => nearToYocto("-1"), Error);
  assert.throws(() => nearToYocto("1.2.3"), Error);
});
